-- check: account_summary.reconcile (total_os, disbursement_amount, demand_amount, repayment_amount, par_over_90, sanctioned_amount)
WITH s AS (SELECT "transaction_date" AS d, count(*) AS n, count(DISTINCT "account_number") AS a, sum("total_os") AS m0, sum("disbursement_amount") AS m1, sum("demand_amount") AS m2, sum("repayment_amount") AS m3, sum("par_over_90") AS m4, sum("sanctioned_amount") AS m5 FROM analytics_poc.v_account_summary_staging GROUP BY 1),
c AS (SELECT "transaction_date" AS d, count(*) AS n, count(DISTINCT "account_number") AS a, sum("total_os") AS m0, sum("disbursement_amount") AS m1, sum("demand_amount") AS m2, sum("repayment_amount") AS m3, sum("par_over_90") AS m4, sum("sanctioned_amount") AS m5 FROM analytics_poc.account_summary_curated GROUP BY 1)
SELECT count(*) AS dates_compared,
  count_if(s.d IS NULL OR c.d IS NULL OR s.n IS DISTINCT FROM c.n OR s.a IS DISTINCT FROM c.a OR s.m0 IS DISTINCT FROM c.m0 OR s.m1 IS DISTINCT FROM c.m1 OR s.m2 IS DISTINCT FROM c.m2 OR s.m3 IS DISTINCT FROM c.m3 OR s.m4 IS DISTINCT FROM c.m4 OR s.m5 IS DISTINCT FROM c.m5) AS mismatched_dates,
  sum(s.n) AS staging_rows, sum(c.n) AS curated_rows, sum(s.m0) AS staging_total_os, sum(c.m0) AS curated_total_os
FROM s FULL OUTER JOIN c ON s.d = c.d;
